   1 package scan
   2 
   3 import (
   4     "bytes"
   5     "path/filepath"
   6     "strings"
   7 
   8     "gopkg.in/yaml.v3"
   9 )
  10 
  11 // Flux repositories (DEVDESK-783). The kustomize-controller of Flux builds an
  12 // overlay with LoadRestrictionsNone, bounded to the root of the artifact (the
  13 // root of the git repository), so an aggregator such as kustomizations/dev may
  14 // list, as resources, Flux Kustomization files of neighbouring folders. kustomize
  15 // with its default restriction refuses them, and the scan reported a HIGH for
  16 // something Flux builds without a problem.
  17 //
  18 // An overlay that kustomize refused for the restriction is built once more
  19 // without it when it is a Flux one: fluxOverlay reads its kustomization the way
  20 // the gate (DEVDESK-771) does and looks for a listed FILE one of whose documents
  21 // is a resource of a group *.toolkit.fluxcd.io.
  22 
  23 const (
  24     // fluxGroupSuffix ends the apiVersion group of every Flux resource
  25     // (kustomize.toolkit.fluxcd.io, helm.toolkit.fluxcd.io, source.toolkit.fluxcd.io…).
  26     fluxGroupSuffix = ".toolkit.fluxcd.io"
  27 
  28     // loadRestrictorFlag is the one argument DevDesk adds to build as Flux does.
  29     loadRestrictorFlag     = "--load-restrictor"
  30     loadRestrictorNoneFlag = loadRestrictorFlag + "=LoadRestrictionsNone"
  31 
  32     // fluxBuiltNote ends the Description of a finding of an overlay that was built
  33     // as Flux builds it and still failed: the failure is not the restrictor's.
  34     fluxBuiltNote = "Built as Flux's kustomize-controller does: files outside the overlay folder allowed, within the repository."
  35 
  36     // fluxKeptNote ends the Description of a finding of a Flux overlay the restrictor
  37     // refused and that was not built again, because allow_remote_bases turns the
  38     // check of its references off (DEVDESK-783).
  39     fluxKeptNote = "This overlay lists Flux resources, which Flux builds without the load restrictor. DevDesk keeps it " +
  40         "while scan.tools.kustomize.allow_remote_bases is true, because that setting turns off its check of what an " +
  41         "overlay references."
  42 
  43     // maxFluxDocuments bounds the documents of one file that are looked at.
  44     maxFluxDocuments = 1024
  45 )
  46 
  47 // userSetsLoadRestrictor reports whether args, the user's own arguments, already
  48 // choose the load restrictor, in the `--load-restrictor=X` or the
  49 // `--load-restrictor X` form. What the user wrote is theirs: DevDesk adds
  50 // nothing next to it and does not build again.
  51 func userSetsLoadRestrictor(args []string) bool {
  52     for _, a := range args {
  53         if a == loadRestrictorFlag || strings.HasPrefix(a, loadRestrictorFlag+"=") {
  54             return true
  55         }
  56     }
  57     return false
  58 }
  59 
  60 // fluxOverlay reports whether the overlay (absolute), inside root (absolute; the
  61 // links are resolved here as vetOverlayIn does), is a Flux one: its kustomization
  62 // lists in `resources` or `bases` at least one FILE with a document whose
  63 // apiVersion group is exactly <name>.toolkit.fluxcd.io.
  64 //
  65 // It reads with the gate's rules: a reference must be localRef, inside root once
  66 // the links are resolved, a regular file (a pipe is never opened) of at most
  67 // lim.FileBytes. A folder is not followed, and `components` and `patches` are
  68 // not looked at. Whatever it cannot read counts as "not Flux".
  69 func fluxOverlay(root, overlay string, lim gateLimits) bool {
  70     root, err := filepath.Abs(root)
  71     if err != nil {
  72         return false
  73     }
  74     if root, err = filepath.EvalSymlinks(root); err != nil {
  75         return false
  76     }
  77     if overlay, err = filepath.Abs(overlay); err != nil {
  78         return false
  79     }
  80     real, err := filepath.EvalSymlinks(overlay)
  81     if err != nil || !within(root, real) {
  82         return false
  83     }
  84     g := &gate{root: root, lim: lim, limit: "the repository"}
  85     file, v := g.kustomizationFile(real)
  86     if file == "" || v.Kind != gateOK {
  87         return false
  88     }
  89     // The kustomization file may itself be a link: what is read is what it names.
  90     if target, err := filepath.EvalSymlinks(file); err != nil || !within(root, target) {
  91         return false
  92     }
  93     node, reason := g.readYAML(file)
  94     if reason != "" {
  95         return false
  96     }
  97     site := gateSite{file: g.rel(file), dir: real}
  98     seen := map[string]bool{}
  99     for _, field := range []string{"resources", "bases"} {
 100         if g.listsFluxFile(fieldNamed(node, field), field, site, seen) {
 101             return true
 102         }
 103     }
 104     return false
 105 }
 106 
 107 // fieldNamed is the value of the field of a kustomization, whatever the case of
 108 // its name: kustomize matches field names without regard to it.
 109 func fieldNamed(n *yaml.Node, name string) *yaml.Node {
 110     if n == nil || n.Kind != yaml.MappingNode {
 111         return nil
 112     }
 113     for i := 0; i+1 < len(n.Content); i += 2 {
 114         if strings.EqualFold(n.Content[i].Value, name) {
 115             return n.Content[i+1]
 116         }
 117     }
 118     return nil
 119 }
 120 
 121 // listsFluxFile reports whether an entry of the list is a regular file that holds
 122 // a Flux document. seen holds the files already read, by real path.
 123 func (g *gate) listsFluxFile(list *yaml.Node, field string, site gateSite, seen map[string]bool) bool {
 124     if list == nil || list.Kind != yaml.SequenceNode {
 125         return false
 126     }
 127     for _, e := range list.Content {
 128         if e.Kind != yaml.ScalarNode || e.Tag != "!!str" {
 129             continue
 130         }
 131         real, found, v := g.resolve(e.Value, field, site)
 132         if v.Kind != gateOK || !found || seen[real] || len(seen) >= g.lim.Visited {
 133             continue
 134         }
 135         seen[real] = true
 136         data, reason := readGateFile(real, min(g.lim.FileBytes, g.lim.TotalBytes-g.read))
 137         if reason != "" { // a folder, a pipe, a file too large or unreadable
 138             continue
 139         }
 140         g.read += int64(len(data))
 141         if hasFluxDocument(data) {
 142             return true
 143         }
 144     }
 145     return false
 146 }
 147 
 148 // hasFluxDocument reports whether a document of the YAML stream data has an
 149 // apiVersion of a Flux group. A stream that stops being YAML ends the search.
 150 func hasFluxDocument(data []byte) bool {
 151     dec := yaml.NewDecoder(bytes.NewReader(data))
 152     for range maxFluxDocuments {
 153         var doc yaml.Node
 154         if err := dec.Decode(&doc); err != nil {
 155             return false
 156         }
 157         if doc.Kind != yaml.DocumentNode || len(doc.Content) != 1 {
 158             continue
 159         }
 160         if v := mapGet(doc.Content[0], "apiVersion"); v != nil && v.Kind == yaml.ScalarNode && isFluxAPIVersion(v.Value) {
 161             return true
 162         }
 163     }
 164     return false
 165 }
 166 
 167 // isFluxAPIVersion reports whether an apiVersion is <name>.toolkit.fluxcd.io/<version>
 168 // with one label before the suffix: a group that goes on after it, or that only
 169 // ends like it, is not Flux's.
 170 func isFluxAPIVersion(apiVersion string) bool {
 171     group, version, ok := strings.Cut(apiVersion, "/")
 172     if !ok || version == "" || strings.Contains(version, "/") {
 173         return false
 174     }
 175     label, ok := strings.CutSuffix(group, fluxGroupSuffix)
 176     return ok && label != "" && !strings.Contains(label, ".")
 177 }
