 		}
 		// kustomize adds no origin to what it emits unless the kustomization
@@ -441,6 +445,81 @@ func (v *k8sValidation) renderKustomizations(ctx context.Context, dirs []string)
 	return nil
 }

+// fluxRetry says what became of the Flux build of an overlay that kustomize
+// refused for its load restrictor (DEVDESK-783).
+type fluxRetry int
+
+const (
+	// fluxNotTried: the overlay was built once.
+	fluxNotTried fluxRetry = iota
+	// fluxBuiltAgain: it was built a second time without the restrictor, and the
+	// result (an error or not) is that of the second build.
+	fluxBuiltAgain
+	// fluxKept: it is a Flux overlay, and the restriction was kept because
+	// allow_remote_bases turns the gate off: there is only one build.
+	fluxKept
+)
+
+// retryAsFlux builds the overlay again, as Flux's kustomize-controller does,
+// when first, the error of the build that just ran, is the load restrictor's and
+// the overlay is a Flux one (fluxOverlay). The gate of DEVDESK-771 has already
+// run before the first build and is not run again: the second build reads
+// nothing the first could not, the restriction left aside, and the paths are
+// bounded to the root the gate and the mount use.
+//
+// A native kustomize with allow_remote_bases is not gated, so DevDesk cannot
+// tell what the overlay would read: it keeps the restriction. It returns the
+// result of the build that holds, the outcome, and the error to report.
+func (v *k8sValidation) retryAsFlux(ctx context.Context, tool ToolSpec, scope renderScope, dir string, first error) ([]byte, fluxRetry, error) {
+	if userSetsLoadRestrictor(tool.Args) || !isLoadRestrictor(failureDetail(first)) {
+		return nil, fluxNotTried, first
+	}
+	root := scope.mount
+	native := tool.Source != ToolSourceContainer
+	if native {
+		root, _ = v.gateScope(ctx)
+	}
+	if !fluxOverlay(root, filepath.Join(v.target, filepath.FromSlash(dir)), defaultGateLimits) {
+		return nil, fluxNotTried, first
+	}
+	if native && v.opts.AllowRemoteBases {
+		return nil, fluxKept, first
+	}
+	log.Printf("[scan/k8s] overlay %q: Flux repository detected, built without the load restrictor (bounded to the repository)", dir)
+	cmd := kustomizeArgs(scope, dir, tool, true)
+	log.Printf("Running: %s", cmd.Loggable())
+	rendered, err := runner.Run(ctx, cmd, nil)
+	return rendered, fluxBuiltAgain, err
+}
+
+// kustomizeFailure is the K8S-RENDER finding of an overlay that does not build.
+// err is the error of the build that holds: the second one when how says the
+// overlay was built as Flux builds it, and the finding then says so and its Repro
+// is that second command.
+func kustomizeFailure(tool ToolSpec, scope renderScope, dir, file string, how fluxRetry, err error) Finding {
+	repro, from := renderRepro(tool, "kustomize", "build", dir)
+	if how == fluxBuiltAgain {
+		repro, from = localRepro(tool, "kustomize", []string{"build", loadRestrictorNoneFlag}, dir)
+	}
+	detail := failureDetail(err)
+	blocked := scope.offline && remoteBlocked(detail, from)
+	steps := renderSteps(SourceKustomize, dir, from, detail, blocked)
+	if how == fluxBuiltAgain {
+		steps = fluxRenderSteps(dir, from, detail, blocked)
+	}
+	f := renderFailure(SourceKustomize, "kustomize", file, "Overlay does not build", from, steps, repro, err)
+	if blocked {
+		markRemoteBlocked(&f)
+	}
+	switch how {
+	case fluxBuiltAgain:
+		f.Description += " " + fluxBuiltNote
+	case fluxKept:
+		f.Description += " " + fluxKeptNote
+	}
+	return f
+}
+
 // gateScope is the limit of the paths the kustomize gate follows, the git
 // repository holding the target or the target itself without one, and what the
 // gate remembers across the overlays of this scan. git is asked once, the first
diff --git i/internal/scan/steps.go w/internal/scan/steps.go
index 2bb18a53..1f22a60d 100644
--- i/internal/scan/steps.go
+++ w/internal/scan/steps.go
@@ -145,6 +145,19 @@ func renderSteps(source, target string, from ToolSource, detail string, blocked
 	return steps
 }

+// fluxRenderSteps are renderSteps for an overlay that was built as Flux builds it
+// (DEVDESK-783) and still failed: the generic step runs the same command, with
+// the flag, so that the error a person reads is the one DevDesk reported and not
+// the load restrictor's.
+func fluxRenderSteps(target string, from ToolSource, detail string, blocked bool) []string {
+	steps := renderSteps(SourceKustomize, target, from, detail, blocked)
+	generic := fmt.Sprintf("Run kustomize build %s and fix the first error it reports.", typedKustomizeDir(target))
+	if len(steps) > 0 && !blocked && quotable(target) && steps[0] == generic {
+		steps[0] = fmt.Sprintf("Run kustomize build --load-restrictor=LoadRestrictionsNone %s and fix the first error it reports.", typedKustomizeDir(target))
+	}
+	return steps
+}
+
 // uncheckedOverlaySteps are the steps for an overlay that was not built because
 // DevDesk could not check its references (DEVDESK-771): dir is the overlay
 // directory and reason what stopped the check.

1	package scan
2	
3	import (
4		"bytes"
5		"context"
6		"errors"
7		"fmt"
8		"io"
9		"io/fs"
10		"os"
11		"path/filepath"
12		"strings"
13		"sync"
14		"syscall"
15		"unicode"
16		"unicode/utf8"
17	
18		"gopkg.in/yaml.v3"
19	)
20	
21	// The native kustomize gate (DEVDESK-771). Go never applies a proxy to the
22	// loopback, so offlineEnviron cannot stop a native kustomize that reads an
23	// overlay naming http://127.0.0.1:8080/x.yaml from sending a GET to a service of
24	// this machine. The overlay is therefore read first, and kustomize is started
25	// only when every reference in it, and in everything it pulls in, can only name
26	// a path of this repository.
27	//
28	// The gate is a closed whitelist, not a list of what to refuse: a reference is
29	// accepted when localRef says it can only be a local path, the YAML is read the
30	// closed way (no anchor, alias, merge key, explicit tag, duplicate key, key that
31	// is not ASCII, second document), every field of the kustomization is one the
32	// gate knows, and every plugin is a builtin one. What it cannot judge is refused
33	// as such: kustomize is not started either. The fields and the plugin kinds are
34	// the ones of kustomize v5.8.3 (api v0.21.3, types.Kustomization and the
35	// builtinhelpers factories).
36	
37	// gateKind is what the gate says about an overlay.
38	type gateKind int
39	
40	const (
41		// gateOK: every reference is local, kustomize may be started.
42		gateOK gateKind = iota
43		// gateRemote: a reference that is not a path of the repository.
44		gateRemote
45		// gateUnchecked: something the gate cannot judge, or cannot read.
46		gateUnchecked
47	)
48	
49	func (k gateKind) String() string {
50		switch k {
51		case gateOK:
52			return "ok"
53		case gateRemote:
54			return "remote"
55		case gateUnchecked:
56			return "unchecked"
57		}
58		return fmt.Sprintf("gateKind(%d)", int(k))
59	}
60	
61	// gateVerdict is the answer for one overlay. File is relative to the limit, with
62	// forward slashes; Field is the YAML path of the entry, with list indices
63	// (resources[1], patches[0].path); for an inline plugin configuration it is the
64	// field of the kustomization followed by the field of the plugin
65	// (transformers[0].path), for a plugin file the field inside that file. Ref is
66	// what localRef was given.
67	type gateVerdict struct {
68		Kind                     gateKind
69		File, Field, Ref, Reason string
70	}
71	
72	// gateLimits bound what the gate reads of a repository that is not trusted.
73	type gateLimits struct {
74		// Depth is the number of levels of overlay below the first; Visited the
75		// number of distinct kustomizations read.
76		Depth, Visited int
77		// FileBytes is the size of one file; TotalBytes of every file read for one
78		// overlay.
79		FileBytes, TotalBytes int64
80	}
81	
82	// defaultGateLimits keep the gate itself cheap: YAML read into nodes costs about a
83	// hundred times the size of the file in memory, so a megabyte per file and eight
84	// for an overlay bound what a repository that is not trusted can make it spend.
85	var defaultGateLimits = gateLimits{Depth: 16, Visited: 256, FileBytes: 1 << 20, TotalBytes: 8 << 20}
86	
87	// localRef reports whether ref can only name a path of this repository. It
88	// accepts a non-empty string without a control character, without ':' (a scheme,
89	// a port, a drive), '@' (an ssh user) or '?' (a query), that is neither absolute
90	// nor starts with a separator, and whose first segment is not github.com (which
91	// kustomize reads as a git repository even when such a folder exists). reason is
92	// "" when it is local, and says why not otherwise.
93	func localRef(ref string) (ok bool, reason string) {
94		switch {
95		case ref == "":
96			return false, "it is empty"
97		case strings.IndexFunc(ref, unicode.IsControl) >= 0:
98			return false, "it holds a control character"
99		case strings.ContainsAny(ref, ":@?"):
100			return false, "it holds a character that a URL, an address or a drive uses"
101		case strings.HasPrefix(ref, "/") || strings.HasPrefix(ref, `\`) || filepath.IsAbs(ref):
102			return false, "it is an absolute path"
103		}
104		if first, _, _ := strings.Cut(ref, "/"); strings.EqualFold(first, "github.com") {
105			return false, "kustomize reads a name that starts with github.com as a git repository"
106		}
107		return true, ""
108	}
109	
110	// ── Reading a file the closed way ────────────────────────────────────────────
111	
112	// readGateYAML reads one file of an overlay and returns the mapping at the top of
113	// its only document. A reason says why it cannot be judged, and the node is nil.
114	func readGateYAML(file string, maxBytes int64) (*yaml.Node, string) {
115		data, reason := readGateFile(file, maxBytes)
116		if reason != "" {
117			return nil, reason
118		}
119		return parseGateYAML(data)
120	}
121	
122	// readGateFile reads a regular file of at most maxBytes.
123	func readGateFile(file string, maxBytes int64) ([]byte, string) {
124		maxBytes = max(maxBytes, 0)
125		info, err := os.Stat(file)
126		if err != nil {
127			return nil, "it cannot be read (" + errReason(err) + ")"
128		}
129		if !info.Mode().IsRegular() {
130			return nil, "it is not a regular file"
131		}
132		tooBig := fmt.Sprintf("it is larger than %d bytes", maxBytes)
133		if info.Size() > maxBytes {
134			return nil, tooBig
135		}
136		f, err := os.Open(file) //nolint:gosec // a file of the repository being scanned, vetted above
137		if err != nil {
138			return nil, "it cannot be read (" + errReason(err) + ")"
139		}
140		defer func() { _ = f.Close() }()
141		// The size may have changed since the stat: one byte more says it did.
142		data, err := io.ReadAll(io.LimitReader(f, maxBytes+1))
143		if err != nil {
144			return nil, "it cannot be read (" + errReason(err) + ")"
145		}
146		if int64(len(data)) > maxBytes {
147			return nil, tooBig
148		}
149		return data, ""
150	}
151	
152	// errReason is err without the path an os error carries.
153	func errReason(err error) string {
154		var pathErr *fs.PathError
155		if errors.As(err, &pathErr) {
156			return pathErr.Err.Error()
157		}
158		return err.Error()
159	}
160	
161	// reasonNoDocument is the reason for a file with nothing in it but comments.
162	const reasonNoDocument = "it holds no YAML document"
163	
164	// parseGateYAML returns the mapping at the top of the only document of data.
165	func parseGateYAML(data []byte) (*yaml.Node, string) {
166		dec := yaml.NewDecoder(bytes.NewReader(data))
167		var doc yaml.Node
168		if err := dec.Decode(&doc); err != nil {
169			if errors.Is(err, io.EOF) {
170				return nil, reasonNoDocument
171			}
172			return nil, "it is not valid YAML"
173		}
174		var next yaml.Node
175		if err := dec.Decode(&next); !errors.Is(err, io.EOF) {
176			return nil, "it holds more than one YAML document"
177		}
178		if doc.Kind != yaml.DocumentNode || len(doc.Content) != 1 || doc.Content[0].Kind != yaml.MappingNode {
179			return nil, "its top level is not a mapping"
180		}
181		top := doc.Content[0]
182		if problem := nodeProblem(top); problem != "" {
183			return nil, "it holds " + problem
184		}
185		return top, ""
186	}
187	
188	// nodeProblem names what makes a node something the gate does not read: kustomize
189	// resolves anchors, aliases and merge keys, applies tags, matches field names
190	// without regard to case (and, for a non-ASCII letter, to Unicode folding) and
191	// keeps the last of two equal keys, so a reading that does not do the same is
192	// not a reading of what kustomize will do.
193	func nodeProblem(n *yaml.Node) string {
194		switch {
195		case n.Kind == yaml.AliasNode:
196			return "an alias"
197		case n.Anchor != "":
198			return "an anchor"
199		case n.Style&yaml.TaggedStyle != 0:
200			return "an explicit tag"
201		}
202		switch n.Kind {
203		case yaml.MappingNode:
204			seen := map[string]bool{}
205			for i := 0; i+1 < len(n.Content); i += 2 {
206				key := n.Content[i]
207				if problem := keyProblem(key, seen); problem != "" {
208					return problem
209				}
210				if problem := nodeProblem(n.Content[i+1]); problem != "" {
211					return problem
212				}
213			}
214		case yaml.SequenceNode:
215			for _, c := range n.Content {
216				if problem := nodeProblem(c); problem != "" {
217					return problem
218				}
219			}
220		}
221		return ""
222	}
223	
224	func keyProblem(key *yaml.Node, seen map[string]bool) string {
225		if problem := nodeProblem(key); problem != "" {
226			return problem
227		}
228		switch {
229		case key.Kind == yaml.ScalarNode && key.Value == "<<":
230			return "a merge key"
231		case key.Kind != yaml.ScalarNode || key.Tag != "!!str":
232			return "a key that is not a string"
233		}
234		for i := 0; i < len(key.Value); i++ {
235			if key.Value[i] >= 0x80 {
236				return "a key that is not ASCII"
237			}
238		}
239		folded := strings.ToLower(key.Value)
240		if seen[folded] {
241			return "a duplicate key"
242		}
243		seen[folded] = true
244		return ""
245	}
