273	// gateRule says how the value of a field is judged: a list judges each of its
274	// elements by elem, a mapping each of its entries by fields (an entry it does
275	// not list holds no reference).
276	type gateRule struct {
277		kind   gateRuleKind
278		elem   *gateRule
279		fields map[string]gateRule
280	}
281	
282	func listOf(r gateRule) gateRule { return gateRule{kind: gateList, elem: &r} }
283	
284	func mapOf(fields map[string]gateRule) gateRule { return gateRule{kind: gateMap, fields: fields} }
285	
286	func lookupRule(fields map[string]gateRule, key string) (gateRule, bool) {
287		for name, r := range fields {
288			if strings.EqualFold(name, key) {
289				return r, true
290			}
291		}
292		return gateRule{}, false
293	}
