21	// The native kustomize gate (DEVDESK-771). Go never applies a proxy to the
22	// loopback, so offlineEnviron cannot stop a native kustomize that reads an
23	// overlay naming http://127.0.0.1:8080/x.yaml from sending a GET to a service of
24	// this machine. The overlay is therefore read first, and kustomize is started
25	// only when every reference in it, and in everything it pulls in, can only name
26	// a path of this repository.
27	//
28	// The gate is a closed whitelist, not a list of what to refuse: a reference is
29	// accepted when localRef says it can only be a local path, the YAML is read the
30	// closed way (no anchor, alias, merge key, explicit tag, duplicate key, key that
31	// is not ASCII, second document), every field of the kustomization is one the
32	// gate knows, and every plugin is a builtin one. What it cannot judge is refused
33	// as such: kustomize is not started either. The fields and the plugin kinds are
34	// the ones of kustomize v5.8.3 (api v0.21.3, types.Kustomization and the
35	// builtinhelpers factories).
36	
37	// gateKind is what the gate says about an overlay.
38	type gateKind int
39	
40	const (
41		// gateOK: every reference is local, kustomize may be started.
42		gateOK gateKind = iota
43		// gateRemote: a reference that is not a path of the repository.
44		gateRemote
45		// gateUnchecked: something the gate cannot judge, or cannot read.
46		gateUnchecked
47	)
48	
49	func (k gateKind) String() string {
50		switch k {
51		case gateOK:
52			return "ok"
53		case gateRemote:
54			return "remote"
55		case gateUnchecked:
56			return "unchecked"
57		}
58		return fmt.Sprintf("gateKind(%d)", int(k))
59	}
