756	// reference judges one reference: it must be local, and below the limit once
757	// symbolic links are resolved. A directory is noted to be read in turn when
758	// follow says so.
759	func (g *gate) reference(ref string, follow bool, field string, s gateSite) gateVerdict {
760		real, found, v := g.resolve(ref, field, s)
761		if v.Kind != gateOK || !found {
762			return v
763		}
764		// Only a regular file or a directory: kustomize blocks on a pipe.
765		info, err := os.Stat(real)
766		switch {
767		case err != nil:
768			return s.unchecked(field, ref, "it cannot be read ("+errReason(err)+")")
769		case info.IsDir():
770			if follow {
771				g.bases = append(g.bases, real)
772			}
773		case !info.Mode().IsRegular():
774			return s.unchecked(field, ref, "it is neither a regular file nor a directory")
775		}
776		return gateVerdict{}
