779	// resolve turns a reference of the kustomization at s.dir into a real path. found
780	// is false for a path that is not there: kustomize reports it and fetches nothing.
781	func (g *gate) resolve(ref, field string, s gateSite) (real string, found bool, v gateVerdict) {
782		if ref == "" {
783			return "", false, gateVerdict{} // the directory of the kustomization itself
784		}
785		if ok, reason := localRef(ref); !ok {
786			return "", false, s.remote(field, ref, reason)
787		}
788		cand := filepath.Join(s.dir, filepath.FromSlash(ref))
789		if !within(g.root, cand) {
790			return "", false, s.unchecked(field, ref, "it leaves "+g.limit)
791		}
792		real, err := filepath.EvalSymlinks(cand)
793		switch {
794		case isMissing(err):
795			return "", false, gateVerdict{}
796		case err != nil:
797			return "", false, s.unchecked(field, ref, "it cannot be resolved ("+errReason(err)+")")
798		case !within(g.root, real):
799			return "", false, s.unchecked(field, ref, "it leaves "+g.limit+" through a symbolic link")
800		}
801		return real, true, gateVerdict{}
802	}
