837	// pluginConfig judges the configuration of a plugin: a builtin one of a known
838	// kind, that runs no function, whose fields that name a file are local.
839	func (g *gate) pluginConfig(node *yaml.Node, prefix string, s gateSite) gateVerdict {
840		scalar := func(name string) string {
841			if n := mapGet(node, name); n != nil && n.Kind == yaml.ScalarNode && n.Tag == "!!str" {
842				return n.Value
843			}
844			return ""
