// renderer runs one tool in the repository, the way every other tool runs:
// in the target for a binary; for an image, with the scope's mount read-only
// at /scan and the target inside it as the working directory.
func renderer(scope renderScope, tool ToolSpec, defaultImage, binary string, args ...string) toolCmd {
	// helm gets them on lint and on template alike: only the flags the two
	// share (--values, --set…) make sense there.
	args = afterSubcommand(args, tool.Args)
	if tool.Source != ToolSourceContainer {
		name := tool.Binary
		if name == "" {
			name = binary
		}
		cmd := toolCmd{Name: name, Args: args, Dir: scope.target}
		if scope.offline {
			cmd.Env = offlineEnviron(os.Environ())
		}
		return cmd
	}
	return containerRun{
		Flags:   []string{"-v", scope.mount + ":" + containerScanPath + ":ro", "-w", scope.workdir()},
		Image:   orDefault(tool.Image, defaultImage),
		Argv:    args,
		Offline: scope.offline,
	}.cmd()
}

func orDefault(v, def string) string {
	if v == "" {
		return def
	}
	return v
}

// renderRepro is the Repro line of a renderer run on target (a chart or an
// overlay directory), run from the scanned directory like the scan did. The
// user's arguments are left out: they may hold a secret (--set password=REDACTED
func renderRepro(tool ToolSpec, name, sub, target string) (string, ToolSource) {
	return localRepro(tool, name, []string{sub}, target)
}

func helmArgs(scope renderScope, chart string, tool ToolSpec, sub string) toolCmd {
	return renderer(scope, tool, DefaultHelmImage, "helm", sub, asPathArg(chart))
}

// kustomizeArgs is `kustomize build dir`. loadAnywhere adds
// --load-restrictor=LoadRestrictionsNone after the user's arguments, as Flux's
// kustomize-controller builds (DEVDESK-783); a restrictor the user chose is theirs
// and nothing is added next to it.
func kustomizeArgs(scope renderScope, dir string, tool ToolSpec, loadAnywhere bool) toolCmd {
	args := []string{"build"}
	if loadAnywhere && !userSetsLoadRestrictor(tool.Args) {
		args = append(args, loadRestrictorNoneFlag)
	}
	return renderer(scope, tool, DefaultKustomizeImage, "kustomize", append(args, asPathArg(dir))...)
}

